-- Quest floors (questing plan WT33a): baked walkable Z candidates (rank <= 4) for the quest POI points no
-- spawn gives a place. Generated by the hub's tools/quest-floors.js (install) from the bake of
-- apps/quest_poi_z_baker, mod-playerbots PR #3035 (5365ac37); do not edit: re-bake and re-install.
-- Navmesh dataset v20-2026-11-17-nv30-vessels; world DB 2026_11_06_01.sql (3279 updates);
-- 1008 quests, 22719 rows; bake SQL sha256 fea5ac424b13c669ace573d0c50412d479d80c5380da27ce4050908018673d3e.
-- Table: mod-playerbots PR #3031 (52a77ddc).
CREATE TABLE IF NOT EXISTS `playerbots_quest_poi_z` (
  `Id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `QuestId` INT UNSIGNED NOT NULL,
  `PoiIdx` SMALLINT UNSIGNED NOT NULL,
  `PointIdx` SMALLINT UNSIGNED NOT NULL,
  `MapId` SMALLINT UNSIGNED NOT NULL,
  `Z` FLOAT NOT NULL,
  `Rank` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `Confidence` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `Evidence` VARCHAR(255) NOT NULL DEFAULT '',
  `NavmeshOk` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `WalkablePoints` TEXT NULL,
  PRIMARY KEY (`Id`), KEY `idx_quest` (`QuestId`, `PoiIdx`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `playerbots_quest_poi_z`;
